exercise.solution:
describe('shippingFee', () => {
  test('คิดค่าส่ง 50 เมื่อยอด 499 ซึ่งต่ำกว่าขอบ', () => {
    expect(shippingFee(499)).toBe(50);
  });

  test('ส่งฟรีเมื่อยอดเท่ากับ 500 พอดี', () => {
    expect(shippingFee(500)).toBe(0);
  });

  test('ยอด 0 ยังคิดค่าส่ง 50 และไม่ throw', () => {
    expect(shippingFee(0)).toBe(50);
  });

  test('throw error เมื่อยอดติดลบ', () => {
    expect(() => shippingFee(-1)).toThrow('invalid total');
  });
});
